+//! Integration tests for Mach4 built-in registry entry (#1968).
+//!
+//! Gate map (M4.4): covers app::posting (BUILTINS, post_serves, post_setup)
+//! with assets/posts/mach4.cps.
+
+use camcraft_app::commands::{
