+        let line = zero
+            .program
+            .lines()
+            .find(|line| line.split_whitespace().any(|w| w == g))
+            .unwrap_or_else(|| panic!("missing {g} for zero dwell:\n{}", zero.program));
+        assert!(
+            !line.split_whitespace().any(|w| w.starts_with('P')),
+            "{g} must not write P: {line}"
+        );
+    }
+}
