+const VERTICAL_THEN_TILTED: &str = "\
+PARAM WorkOffset G54
+PARAM ClearancePlane 25
+TOOL 1 \"6MM EM\"
+PARAM SpindleSpeed 8000
+SECTION Vertical
+Rapid X 10000 Y 5000 Z 10000
+Feed X 10000 Y 5000 Z 0 F 400000
+ENDSECTION
+SECTION Tilted
